    if (app_ptr->XA < xmin) {
      xmin = app_ptr->XA;
    }
    if (app_ptr->XA > xmax) {
      xmax = app_ptr->XA;
    }
    if (app_ptr->YA < ymin) {
      ymin = app_ptr->YA;
    }
    if (app_ptr->YA > ymax) {
      ymax = app_ptr->YA;
    }
